<script setup>
import {ref,onMounted,computed} from 'vue';
import TrendChart from '@/components/TrendChart.vue';
import AnalyticsChart from '@/components/AnalyticsChart.vue';
import {supabase} from '@/config/supabase';
import {ACTIVITY_TYPES} from '@/lib/activity-types';
import {artistTypeLabels} from '@/lib/artistFilters';
import {csvText,percent} from '@/lib/analytics';
const now=new Date(),filters=ref({start:now.getFullYear()+'-01-01',end:now.getFullYear()+'-12-31',kind:'personal',genre:'',category:'',region:'',city:'',status:'effective',participation:'',compare:'previous',grain:'month',search:'',sort:'desc',top:'0',row_dim:'subject',col_dim:'category'});
const data=ref(null),busy=ref(false),error=ref(''),tab=ref('rankings'),subject=ref(null),page=ref(0),applied=ref(null),exporting=ref(false);
const attendance=ref(false);
async function toggleAttendance(){attendance.value=!attendance.value;await query(false);}
let request=0;
const drill=ref(null);
const dimensions={subject:'统计主体',category:'活动类别',region:'地区',month:'月份',participation:'参与方式'};
const crossLabel=(value,dim)=>dim==='category'?label(value):dim==='participation'?(participationLabels.value[value]||value):value;
const crossCount=(row,col)=>Number(data.value?.cross_cells.find(c=>c.row_key===row&&c.col_key===col)?.n||0);
async function crossDetails(row,col){drill.value={cross_row_value:row.row_key,cross_col_value:col};subject.value=applied.value.row_dim==='subject'?row.row_key:null;page.value=0;tab.value='details';await query(false);}
async function trendDetails(period){drill.value={period_value:period};page.value=0;tab.value='details';await query(false);}
async function backToCross(){const wasTrend=!!drill.value?.period_value;drill.value=null;subject.value=null;page.value=0;tab.value=wasTrend?'months':'cross';await query(false);}

const dirty=computed(()=>applied.value&&JSON.stringify(filters.value)!==JSON.stringify(applied.value));
const participationLabels=ref({});
const growth=(n,previous)=>previous?((n-previous)/previous*100).toFixed(1)+'%':n?'新增（上期为0）':'—';
const matrixCount=(id,category)=>Number(data.value?.matrix.find(r=>r.id===id&&r.category===category)?.n||0);
async function categoryRank(category){filters.value={...applied.value,category};tab.value='rankings';await query();}
async function cellDetails(row,category){filters.value={...applied.value,category};applied.value={...filters.value};await detail(row,'details');}
async function geographic(region){filters.value={...applied.value,region};tab.value='rankings';await query();}

const label=id=>ACTIVITY_TYPES.find(x=>x.id===id)?.name||id;
async function query(reset=true){if(reset){attendance.value=false;drill.value=null;if(tab.value==='profile')tab.value='rankings';page.value=0;subject.value=null;applied.value={...filters.value};}const token=++request;busy.value=true;error.value='';try{const {data:result,error:e}=await supabase.rpc('chob_analytics',{filters:{...applied.value,...drill.value,date_basis:attendance.value&&subject.value?'attendance':'event'},subject:subject.value,page_number:page.value});if(e)throw e;if(token===request)data.value=result;}catch(e){if(token===request){error.value=e.message;data.value=null;}}finally{if(token===request)busy.value=false;}}
async function detail(row,view='profile'){attendance.value=false;subject.value=row.id;page.value=0;tab.value=view;await query(false);}
async function turn(delta){page.value+=delta;await query(false);}
async function changeTab(value){attendance.value=false;const reload=subject.value!==null||page.value!==0||drill.value!==null;drill.value=null;tab.value=value;subject.value=null;page.value=0;if(reload)await query(false);}
async function download(){exporting.value=true;error.value='';const scope={...applied.value,...drill.value,date_basis:attendance.value&&subject.value?'attendance':'event'},target=subject.value,view=tab.value;try{
let rows=[];for(let p=0;;p++){
 const {data:d,error:e}=await supabase.rpc('chob_analytics',{filters:scope,subject:target,page_number:p});if(e)throw e;
 if(view==='cross'){if(!p)rows.push([dimensions[scope.row_dim],...d.cross_columns.map(c=>crossLabel(c,scope.col_dim))]);for(const r of d.cross_rows)rows.push([crossLabel(r.row_name,scope.row_dim),...d.cross_columns.map(c=>d.cross_cells.find(v=>v.row_key===r.row_key&&v.col_key===c)?.n||0)]);if(d.cross_rows.length<100)break;}
 else if(view==='matrix'){if(!p)rows.push(['主体',...d.options.categories.map(label)]);for(const r of d.rankings)rows.push([r.name,...d.options.categories.map(c=>d.matrix.find(m=>m.id===r.id&&m.category===c)?.n||0)]);if(d.rankings.length<100)break;}
 else if(view==='quality'){if(!p)rows.push(['活动ID','日期','活动','待核对问题']);for(const r of d.quality)rows.push([r.id,r.date,r.title,r.issue]);if(d.quality.length<100)break;}
 else if(['details','profile'].includes(view)){if(!p)rows.push(['活动ID','日期','活动','类别','地区','城市']);for(const r of d.details)rows.push([r.id,r.date,r.title,label(r.category),r.region,r.city]);if(d.details.length<100)break;}
 else if(['categories','months','geography'].includes(view)){const list=view==='categories'?d.categories:view==='months'?d.trend:d.regions;rows=[['类别 / 月份 / 地区','活动数量','活动占比'],...list.map(r=>[r.period||r.month_key||label(r.category),r.n,percent(r.n,d.total)])];break;}
 else {if(!p)rows.push(['排名','名称','活动次数','活动占比','比较活动总数','上期次数','变化']);for(const r of d.rankings)rows.push([r.position,r.name,r.n,percent(r.n,d.total),d.total,d.comparison.available?r.previous_n:'',d.comparison.available?growth(r.n,r.previous_n):'']);if(d.rankings.length<100)break;}
}
const url=URL.createObjectURL(new Blob([csvText(rows)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='chob-'+view+'.csv';a.click();URL.revokeObjectURL(url);
}catch(e){error.value=e.message;}finally{exporting.value=false;}}
onMounted(async()=>{query();const {data:conditions}=await supabase.from('participation_conditions').select('code,name');participationLabels.value=Object.fromEntries((conditions||[]).map(c=>[c.code,c.name]));});
</script>
<template><section class="space-y-6"><header><h1 class="text-2xl font-bold">数据统计与分析</h1><p class="text-gray-500 mt-2">本数据基于 Chob Calendar 已收录活动，不代表行业全部活动。</p></header>
<form @submit.prevent="query()" class="bg-white rounded-xl p-5 grid sm:grid-cols-3 gap-4">
<label>开始日期<input class="input" type="date" v-model="filters.start" /></label><label>结束日期<input class="input" type="date" v-model="filters.end" /></label>
<label>主体<select class="input" v-model="filters.kind"><option value="personal">个人身份</option><option value="cp">CP身份</option><option value="group">团体 / 乐队</option></select></label>
<label>艺人类别<select class="input" v-model="filters.genre"><option value="">全部类别</option><option v-for="(v,k) in artistTypeLabels" :key="k" :value="k">{{v}}</option></select><small v-if="filters.kind==='cp'">CP类别按成员资料匹配，活动仍只算明确CP身份。</small></label>
<label>活动类别<select class="input" v-model="filters.category"><option value="">全部活动</option><option v-for="v in data?.options.categories||[]" :key="v" :value="v">{{label(v)}}</option></select></label>
<label>地区<select class="input" v-model="filters.region"><option value="">全部地区</option><option v-for="v in ['泰国','中国','海外','待确认']" :key="v">{{v}}</option></select></label>
<label>城市<select class="input" v-model="filters.city"><option value="">全部城市</option><option v-for="v in data?.options.cities||[]" :key="v">{{v}}</option></select></label>
<label>趋势粒度<select class="input" v-model="filters.grain"><option value="day">每日</option><option value="week">每周（周一开始）</option><option value="month">每月</option><option value="quarter">每季度</option><option value="year">每年</option></select></label>
<label>排行名称<input class="input" v-model="filters.search" placeholder="搜索艺人、CP或团体名称" maxlength="100" /></label>
<label>排序<select class="input" v-model="filters.sort"><option value="desc">活动次数从多到少</option><option value="asc">活动次数从少到多</option></select></label>
<label>排行范围<select class="input" v-model="filters.top"><option value="0">全部主体</option><option v-for="n in [10,20,50,100]" :key="n" :value="String(n)">Top {{n}}</option></select></label>
<label>交叉分析 · 行<select class="input" v-model="filters.row_dim"><option v-for="(name,key) in dimensions" :key="key" :value="key">{{name}}</option></select></label>
<label>交叉分析 · 列<select class="input" v-model="filters.col_dim"><option v-for="(name,key) in dimensions" :key="key" :value="key" :disabled="key==='subject'">{{name}}</option></select></label>
<label>对比周期<select class="input" v-model="filters.compare"><option value="previous">前一个等长周期</option><option value="year">去年同期</option></select></label><label>参与方式<select class="input" v-model="filters.participation"><option value="">全部参与方式</option><option v-for="v in data?.options.participation||[]" :key="v" :value="v">{{participationLabels[v]||'其他参与方式'}}</option></select></label><label>活动范围<select class="input" v-model="filters.status"><option value="effective">有效且已发布</option><option value="all">全部发布及业务状态</option></select></label><button class="btn-primary rounded-lg" :disabled="busy">{{busy?'查询中…':'应用筛选'}}</button></form>
<p v-if="dirty" role="status" class="rounded-lg bg-amber-50 p-3 text-sm text-amber-800">筛选条件已修改，尚未应用。下方仍是上次查询结果。 <button class="underline" @click="query()">立即应用</button></p>
<p v-if="error" role="alert" class="text-red-700">{{error}} <button @click="query(false)">重试</button></p>
<template v-if="data"><div class="grid sm:grid-cols-4 gap-4"><div class="card"><span>筛选内独立活动</span><b>{{data.total}}</b></div><div class="card"><span>有活动的主体</span><b>{{data.participating}}</b></div><div class="card"><span>活跃主体 · 前50%含并列</span><b>{{data.active}}</b></div><div class="card"><span>主体覆盖率</span><b>{{percent(data.covered,data.catalog_total)}}</b><small>{{data.covered}} / {{data.catalog_total}} 个有效资料</small></div></div>
<p class="text-sm text-gray-500">只统计明确选择的身份，团体和CP活动不分摊给个人。活动占比分母为当前筛选的 {{data.total}} 场独立活动，多人活动的占比之和可能超过100%。</p>
<nav class="flex flex-wrap gap-3"><button v-for="[k,v] in [['overview','数据总览'],['rankings','排行榜'],['categories','类别分析'],['months','时间趋势'],['geography','地区分析'],['matrix','主体类别矩阵'],['cross','自由交叉分析'],['details','活动明细'],['quality','数据质量']]" :key="k" :class="tab===k?'btn-primary':'btn-secondary'" class="px-4 py-2 rounded-lg" @click="changeTab(k)">{{v}}</button><button @click="download" :disabled="exporting||busy" class="btn-secondary px-4 py-2">{{exporting?'导出中…':'导出当前分析 CSV'}}</button></nav>
<p v-if="data.comparison?.available&&!attendance" class="text-sm text-gray-500">{{applied.compare==='year'?'去年同期':'前一个等长周期'}}：{{data.comparison.start}} 至 {{data.comparison.end}}，共 {{data.comparison.previous_total}} 场；本期变化 {{growth(data.total,data.comparison.previous_total)}}。<span v-if="data.comparison.incomplete">本期含未结束或未来日期，仅反映收录变化。</span></p><p v-if="busy" role="status">正在查询…</p>
<div v-else class="bg-white rounded-xl p-5 overflow-x-auto">
<p v-if="tab==='rankings'" class="text-sm text-gray-500 mb-4">匹配 {{data.ranking_total}} 个主体；搜索、排序及 Top 范围不改变活动占比的分母。Top N 按次数降序选取，包含相同次数时按名称与编号稳定截取。</p><section v-if="tab==='overview'"><h2 class="text-xl font-bold mb-4">当前筛选范围</h2><div class="grid sm:grid-cols-3 gap-4"><div class="card"><span>活动类别</span><b>{{data.overview.categories}}</b></div><div class="card"><span>城市原始名称</span><b>{{data.overview.cities}}</b></div><div class="card"><span>地区分组</span><b>{{data.overview.regions}}</b></div></div><h3 class="font-semibold mt-6 mb-3">全库收录与待处理</h3><p class="text-sm text-gray-500 mb-3">以下不受上方筛选影响；排除回收站与已合并记录。发布状态和活动业务状态可能重叠。</p><div class="grid sm:grid-cols-3 gap-4"><div v-for="[key,name] in [['records','收录记录'],['drafts','草稿'],['undated','日期未定'],['cancelled','已取消'],['postponed','已延期']]" :key="key" class="card"><span>{{name}}</span><b>{{data.overview[key]}}</b></div></div></section><table v-else-if="tab==='rankings'" class="w-full text-left"><thead><tr><th>排名</th><th>主体</th><th>活动次数</th><th>活动占比</th><th>上期 / 变化</th></tr></thead><tbody><tr v-for="r in data.rankings" :key="r.id"><td>{{r.position}}</td><td><button class="text-primary-600 underline" @click="detail(r)">{{r.name}}</button>{{r.archived?'（历史资料）':''}}</td><td><button class="text-primary-600 underline" @click="detail(r,'details')">{{r.n}} · 查看活动</button></td><td>{{percent(r.n,data.total)}}</td><td>{{data.comparison?.available?(r.previous_n+' / '+growth(r.n,r.previous_n)):'请选择起止日期'}}</td></tr></tbody></table>
<template v-else-if="tab==='profile'"><div class="flex flex-wrap items-center justify-between gap-3 mb-5"><h2 class="text-xl font-bold">{{data.subject_name}} · 身份活动分析</h2><button class="btn-secondary px-4 py-2" @click="tab='details'">查看 {{data.detail_total}} 场原始活动</button></div><button class="btn-secondary px-4 py-2 mb-4" @click="toggleAttendance">{{attendance?'切回活动开始日期':'按该艺人月行程出席日期查看'}}</button><p v-if="attendance" class="text-sm text-gray-500 mb-4">优先使用该主体的有效月行程日期；未录入时沿用活动日期。同一活动在所选范围只计一次，多日出席取范围内最早一天。本视图暂不显示上期对比。</p><p v-if="!attendance" class="text-sm text-gray-500 mb-5">本期 {{data.detail_total}} 场 · 上期 {{data.subject_previous}} 场 · {{growth(data.detail_total,data.subject_previous)}}。仅统计该主体明确身份，不继承成员活动。</p><div v-if="data.members?.length" class="rounded-lg bg-gray-50 p-4 mb-6"><h3 class="font-semibold mb-2">{{applied.kind==='cp'?'CP成员个人身份活动':'当前团体成员个人身份活动'}}</h3><p class="text-xs text-gray-500 mb-3">按当前成员资料展示，仅算明确个人身份；历史团体活动不分摊给成员。同场个人身份共 {{data.member_same_stage}} 场，不等同于CP或团体活动。</p><div v-for="m in data.members" :key="m.id" class="flex justify-between py-1 text-sm"><span>{{m.name}}</span><span>{{m.n}} 场</span></div></div><AnalyticsChart mode="categories" :rows="data.categories" :total="data.detail_total" @select-category="cellDetails({id:subject},$event)"/><AnalyticsChart class="mt-8" mode="months" :rows="data.months" :total="data.detail_total" :start="applied.start" :end="applied.end" /></template>
<template v-else-if="tab==='cross'"><h2 class="text-xl font-bold mb-2">{{dimensions[applied.row_dim]}} × {{dimensions[applied.col_dim]}}</h2><p class="text-sm text-gray-500 mb-5">按独立活动去重。每页100行，列最多展示100项；共 {{data.cross_columns_total}} 列。点击有数量的格子查看原始活动。</p><table class="w-full text-left"><thead><tr><th>{{dimensions[applied.row_dim]}}</th><th v-for="c in data.cross_columns" :key="c">{{crossLabel(c,applied.col_dim)}}</th></tr></thead><tbody><tr v-for="r in data.cross_rows" :key="r.row_key"><td>{{crossLabel(r.row_name,applied.row_dim)}}</td><td v-for="c in data.cross_columns" :key="c"><button class="matrix-cell" :disabled="!crossCount(r.row_key,c)" :style="{background:crossCount(r.row_key,c)?'rgba(111,143,189,'+(0.12+0.75*crossCount(r.row_key,c)/Math.max(r.n,1))+')':'#f7f8fa'}" @click="crossDetails(r,c)">{{crossCount(r.row_key,c)}}</button></td></tr></tbody></table><p v-if="!data.cross_rows.length" class="text-gray-500 py-6">当前范围没有可交叉统计的数据。</p></template>
<template v-else-if="tab==='matrix'"><h2 class="text-xl font-bold mb-2">主体 × 活动类别</h2><p class="text-sm text-gray-500 mb-5">点击格子查看对应活动，每页100个主体。</p><table class="w-full text-left"><thead><tr><th>主体</th><th v-for="c in data.options.categories" :key="c">{{label(c)}}</th></tr></thead><tbody><tr v-for="r in data.rankings" :key="r.id"><td>{{r.name}}</td><td v-for="c in data.options.categories" :key="c"><button :disabled="!matrixCount(r.id,c)" class="matrix-cell" :style="{background:matrixCount(r.id,c)?'rgba(111,143,189,'+(0.12+0.75*matrixCount(r.id,c)/Math.max(r.n,1))+')':'#f7f8fa'}" @click="cellDetails(r,c)">{{matrixCount(r.id,c)}}</button></td></tr></tbody></table></template>
<template v-else-if="tab==='geography'"><h2 class="text-xl font-bold mb-2">地区与城市</h2><p class="text-sm text-gray-500 mb-5">点击地区进入该地区排行。城市保留原始填写名称，尚未合并中英文别名。</p><AnalyticsChart mode="regions" :rows="data.regions" :total="data.total" @select-category="geographic"/><h3 class="font-semibold mt-6 mb-3">城市数量（前100项）</h3><div v-for="r in data.cities" :key="r.category" class="flex justify-between border-b py-2 text-sm"><span>{{r.category||'未填写'}}</span><span>{{r.n}} 场</span></div></template>
<TrendChart v-else-if="tab==='months'" :rows="data.trend" :grain="applied.grain" @select-period="trendDetails"/><AnalyticsChart v-else-if="tab==='categories'" :mode="tab" :rows="tab==='categories'?data.categories:data.months" :total="data.total" :start="applied?.start" :end="applied?.end" @select-category="categoryRank" />
<template v-else-if="tab==='details'"><button v-if="drill" class="btn-secondary px-4 py-2 mb-4" @click="backToCross">返回分析</button><p class="mb-3">{{subject?'所选主体':'筛选范围'}}对应 {{data.detail_total}} 场活动</p><table class="w-full text-left"><tbody><tr v-for="r in data.details" :key="r.id"><td>{{r.date||'日期待定'}}</td><td><router-link :to="{path:'/events',query:{edit:r.id}}" target="_blank" rel="noopener" class="text-primary-600 underline">{{r.title}} · 查看／修正</router-link></td><td>{{label(r.category)}}</td><td>{{r.city}}</td></tr></tbody></table></template>
<template v-else><div class="grid sm:grid-cols-4 gap-3 mb-5"><div v-for="[key,name] in [['date','日期未定'],['artists','未关联艺人'],['region','地区待确认'],['category','缺少分类']]" :key="key" class="card"><span>{{name}}</span><b>{{data.quality_summary[key]}}</b></div></div><p class="mb-3">全库数据质量：{{data.quality_total}} 条需要核对（不受上方筛选影响）</p><table class="w-full text-left"><tbody><tr v-for="r in data.quality" :key="r.id"><td>{{r.date||'日期待定'}}</td><td>{{r.title}}<small class="block text-gray-400">{{r.id}}</small></td><td class="text-amber-700">{{r.issue}}</td></tr></tbody></table></template>
<section v-if="tab==='quality'" class="mt-8"><h3 class="font-semibold">疑似重复候选 · {{data.duplicate_total}} 对</h3><p class="text-sm text-gray-500 my-3">同名、同日、同城市的不同记录，仅供人工核对，可能是合法的不同场次；不会自动合并或删除。每页最多100对，与上方问题列表共用页码。</p><div v-for="r in data.duplicates" :key="r.first_id+'-'+r.second_id" class="border-b py-3"><p>{{r.date}} · {{r.title}} · {{r.city}}</p><router-link :to="{path:'/events',query:{edit:r.first_id}}" target="_blank" rel="noopener" class="text-primary-600 underline mr-4">打开记录一</router-link><router-link :to="{path:'/events',query:{edit:r.second_id}}" target="_blank" rel="noopener" class="text-primary-600 underline">打开记录二</router-link></div></section><p v-if="(tab==='rankings'&&!data.rankings.length)||(tab==='details'&&!data.details.length)" class="py-8 text-gray-500">此范围没有可统计的活动。</p>
<div v-if="['rankings','matrix','cross','details','quality'].includes(tab)" class="flex gap-4 mt-5"><button :disabled="page===0" @click="turn(-1)">上一页</button><span>第 {{page+1}} 页 · 每页100条</span><button :disabled="(page+1)*100>=(tab==='cross'?data.cross_total:['rankings','matrix'].includes(tab)?data.ranking_total:tab==='details'?data.detail_total:Math.max(data.quality_total,data.duplicate_total))" @click="turn(1)">下一页</button></div>
</div></template></section></template>
<style scoped>.input{display:block;width:100%;border:1px solid #d1d5db;border-radius:8px;padding:9px;margin-top:6px;background:white}label{font-size:14px}.card{background:white;border-radius:12px;padding:20px;display:flex;flex-direction:column;gap:8px}.card span,small{color:#6b7280}.card b{font-size:28px}th,td{padding:14px 10px;border-bottom:1px solid #eee}.matrix-cell{min-width:42px;padding:8px;border-radius:6px;font-variant-numeric:tabular-nums}button:disabled{opacity:.45}</style>
